"""Independent generic PDF generated by scripts/generate_formatting_holdout.py.

The PDF must be processed/exported with the CLI before this opt-in assertion.
"""
import json
import os
from pathlib import Path
import pytest
from local_vector_batch.document_blocks import validate_blocks


@pytest.mark.skipif(not os.environ.get('PDF2DATA_FORMATTING_HOLDOUT'), reason='holdout CLI export not configured')
def test_generic_nested_list_and_merged_header_cli_export():
    root = Path(os.environ['PDF2DATA_FORMATTING_HOLDOUT'])
    data = json.loads((root / 'data.json').read_text())
    md = (root / 'document.md').read_text()
    validate_blocks(data['document_blocks'], data['pages'])
    blocks = data['document_blocks']['blocks']
    items = [(b['marker'], b['list_depth_candidate']) for b in blocks if b['kind'] == 'list_item']
    assert items == [('(a)', 0), ('(i)', 1), ('(ii)', 1), ('(b)', 0), ('(c)', 0)]
    assert md.index('Readings:') < md.index('<table') < md.index('Next step:')
    assert '<th colspan="2">Electrical measurements</th>' in md
    assert md.count('Electrical measurements') == 1
    assert data['tables'][0]['cells'] == [['Electrical measurements', None], ['Voltage', '230 V']]
    assert data['tables'][0]['cell_spans'][0]['column_span'] == 2
    assert not data['document_blocks']['unresolved_tables']
    assert all(b['semantic_state'] == 'candidate' for b in blocks)
    assert not data['publication_eligible']
